def evaluate_truth(statement, context):
  """
  Evaluates the 'Truth' of a statement based on 'Harm Reduction' (Axiom 3) rather than raw 'Factuality'.

  Args:
    statement: The statement being evaluated (string).
    context: A dictionary containing information about the situation, including:
      - 'lie': True if the statement is a lie, False otherwise.
      - 'family_at_risk': True if the family is at risk of significant harm, False otherwise.
      - 'harm_level':  A string indicating the severity of potential harm: "low", "moderate", "high", "critical".
      - 'alternative_options': A list of alternative actions considered, and their potential outcomes.  (Optional)

  Returns:
    A string representing the ethical evaluation: "Truthful", "Acceptable", "Questionable", "Unethical".
  """

  if not isinstance(context, dict):
    return "Unethical"  # Invalid context - can't evaluate

  if 'lie' not in context or 'family_at_risk' not in context or 'harm_level' not in context:
    return "Unethical"  # Missing critical context information

  is_lie = context['lie']
  family_at_risk = context['family_at_risk']
  harm_level = context['harm_level']

  if not is_lie:
    return "Truthful"  # If it's not a lie, it's truthful

  if not family_at_risk:
    return "Questionable" # Lying when no harm is at stake is generally questionable.

  if harm_level == "critical":
    return "Acceptable"  # Lying to prevent immediate, critical harm is generally acceptable.

  if harm_level == "high":
    return "Acceptable"  # Lying to prevent significant harm is often acceptable.

  if harm_level == "moderate":
    if 'alternative_options' in context:
      if any(option['outcome'] == 'harm_avoided' for option in context['alternative_options']):
        return "Questionable" # If other options existed to avoid harm, lying is more questionable.
      else:
        return "Acceptable" # Lying is more acceptable
